from typing import *

class Solution:
    def maximumTastiness(self, price: List[int], k: int) -> int:
        price.sort()
        n = len(price)

        # Check if it's possible to pick k candies with minimum difference of 'diff'
        def can_achieve(diff: int) -> bool:
            count = 1
            last = price[0]
            for i in range(1, n):
                if price[i] - last >= diff:
                    count += 1
                    last = price[i]
                    if count >= k:
                        return True
            return False

        # Binary search on the answer
        low = 0
        high = price[-1] - price[0]
        result = 0

        while low <= high:
            mid = (low + high) // 2
            if can_achieve(mid):
                result = mid
                low = mid + 1
            else:
                high = mid - 1

        return result
